package org.peirs.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="projects") public class Project { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="project_code",unique=true,nullable=false) public String projectCode; @Column(nullable=false) public String title; @Column(columnDefinition="text") public String description; @Column(nullable=false) public String category; @Column(nullable=false) public String department; @ManyToOne @JoinColumn(name="owner_id") public User owner; @Column(columnDefinition="text") public String objectives; @Column(name="expected_outcomes",columnDefinition="text") public String expectedOutcomes; @Column(name="timeline_months") public Integer timelineMonths=12; @Column(nullable=false) public BigDecimal investment=BigDecimal.ZERO; @Column(name="annual_revenue") public BigDecimal annualRevenue=BigDecimal.ZERO; @Column(name="annual_cost") public BigDecimal annualCost=BigDecimal.ZERO; @Column(name="lifespan_years") public Integer lifespanYears=5; @Column(name="strategic_importance") public Integer strategicImportance=70; @Column(name="technical_feasibility") public Integer technicalFeasibility=70; @Column(nullable=false) public String status="SUBMITTED"; @Column(name="created_at",insertable=false,updatable=false) public Instant createdAt; @Column(name="updated_at",insertable=false,updatable=false) public Instant updatedAt; }
